MATCH (item:PlantItem {tag: 'P-901A'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem:PlateHeatExchanger {unit_id: '36'})
RETURN item.tag AS tag
ORDER BY tag;

MATCH (f:ProcessInstrumentationFunction {loop_tag: 'BSL-15029'})-[:send_signal_to*1..]->(a:PlantItem)-[:control]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem:RotaryPump {unit_id: '6'})
RETURN p.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-4601'}), (b:PlantItem {tag: 'TK-4602'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN count(DISTINCT v) AS valve_count, collect(DISTINCT v.tag) AS valve_tags

MATCH (a:PlantItem {tag: 'H-4301'}), (b:PlantItem {tag: 'E-4301'}), (r:PlantItem {tag: 'R-4301'})
RETURN EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE x <> r AND y <> r)+ (b)
} AS reachable

MATCH (v:PlantItem:GateValve {unit_id: '31'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (h:PlantItem {tag: 'H-3701'})-[:line_to]-(v:Valve)<-[:control]-(a:PlantItem {kind: 'actuator'})<-[:send_signal_to*1..]-(loop:ProcessControlFunction)
RETURN DISTINCT loop.loop_tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:SpringLoadedAngleGlobeSafetyValve {unit_id: '40'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'F-201A'}), (b:PlantItem {tag: 'V-301'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'V-3001'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'K-3801'}), (b:PlantItem {tag: 'F-3801'}), (excluded:PlantItem {tag: 'EA-3801'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH p = shortestPath((a)-[:line_to*]->(b))
         WHERE NONE(n IN nodes(p) WHERE n = excluded)
       } AS can_flow_without_EA-3801

MATCH (item:PlantItem {tag: 'EA-1701'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet
ORDER BY sheet;

MATCH (a:PlantItem {tag: 'K-3801'}), (b:PlantItem {tag: 'F-3801'}), (excluded:PlantItem {tag: 'EA-3801'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH p = shortestPath((a)-[:line_to*]->(b))
         WHERE NONE(n IN nodes(p) WHERE n = excluded)
       } AS can_flow_without_EA_3801

MATCH (a:PlantItem {tag: 'P-3701C'}), (b:PlantItem {tag: 'E-3901'}), (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'T-2701'}), (b:PlantItem {tag: 'TK-2802'}), (blocked:PlantItem {tag: 'P-2701A'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((n)-[:line_to]->(m) WHERE m <> blocked)+ (b)
       } AS reachable_without_P_2701A

MATCH (p:PlantItem {tag: 'P-4501C'}), (e:PlantItem {tag: 'E-4701'}), (v:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'TK-1004'}), (b:PlantItem {tag: 'P-1101B'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE y.tag <> 'P-1001A')+ (b)
       } AS reachable_without_P_1001A

MATCH (a:PlantItem {tag: 'EA-501'}), (b:PlantItem {tag: 'P-601B'}), (v:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-4201A'}), (b:PlantItem {tag: 'TK-4602'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN count(DISTINCT v) AS valve_count, collect(DISTINCT v.tag) AS valve_tags

MATCH (a:PlantItem {tag: 'TK-1001'}), (b:PlantItem {tag: 'P-1301B'})
RETURN a.tag AS source_tag, b.tag AS target_tag,
       EXISTS { (a)-[:line_to*1..]->(b) } AS reachable;

MATCH (a:PlantItem {tag: 'T-2101'}), (b:PlantItem {tag: 'T-2701'}), (e:PlantItem {tag: 'E-2102'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE y <> e)+ (b)
       } AS can_flow_without_e2102

MATCH (a:PlantItem {tag: 'P-701B'}), (b:PlantItem {tag: 'V-1101'})
RETURN EXISTS {
  MATCH p = shortestPath((a)-[:line_to*]->(b))
  WHERE none(n IN nodes(p) WHERE n.tag = 'YV-8012')
} AS can_flow

MATCH (a:PlantItem {tag: 'P-2001A'}), (b:PlantItem {tag: 'P-3901B'}), (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'V-901'}), (b:PlantItem {tag: 'TK-4102'})
WHERE EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x.tag <> 'YV-28001' AND y.tag <> 'YV-28001')+ (b)
}
RETURN a.tag AS from_tag, b.tag AS to_tag

MATCH (s:PlantItem {tag: 'STR-21046'})
MATCH (v:PlantItem:ButterflyValve {line_number: '6-P-210050-A1A-N'})-[:line_to*1..]->(s)
WHERE NOT EXISTS {
  MATCH (w:PlantItem:ButterflyValve {line_number: '6-P-210050-A1A-N'})-[:line_to*1..]->(s)
  WHERE w <> v AND EXISTS { (v)-[:line_to*1..]->(w) }
}
RETURN v.tag AS tag, coalesce(v.operating_position, 'NO') AS operating_position
ORDER BY tag

MATCH (y:PlantItem {tag: 'YV-10001'})
MATCH (v:PlantItem:GateValve {line_number: '6-P-100001-A1A-N'})-[:line_to*1..]->(y)
RETURN v.tag AS tag, coalesce(v.operating_position, 'NO') AS normal_position ORDER BY tag;

MATCH (y:PlantItem {tag: 'YV-23001'}),
      (v:PlantItem:GlobeValve {line_number: '4-P-220001-A1A-N'})
WHERE (v)-[:line_to*1..]->(y)
  AND NOT EXISTS {
    MATCH (v)-[:line_to*1..]->(w:PlantItem:GlobeValve {line_number: '4-P-220001-A1A-N'})-[:line_to*1..]->(y)
    WHERE w <> v
  }
RETURN v.tag AS tag, v.operating_position AS operating_position
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(t:PlantItem {tag: 'TK-1001'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(e:PlantItem {tag: 'EJ-4001A'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(r:PlantItem {tag: 'R-1501'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(:PlantItem {tag: 'EA-1501'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;
